                        <script>
                        (function () {
                                var localViewerState = {
                                        initialized: false,
                                        engine: null,
                                        scene: null,
                                        canvas: null
                                };

                                function getSceneWrapper() {
                                        return document.querySelector('.bolin-scene-wrapper');
                                }

                                function fitCameraToScene(camera, scene) {
                                        var min = null;
                                        var max = null;

                                        scene.meshes.forEach(function (mesh) {
                                                if (!mesh.getTotalVertices || mesh.getTotalVertices() === 0) {
                                                        return;
                                                }

                                                mesh.computeWorldMatrix(true);
                                                var info = mesh.getBoundingInfo();
                                                if (!info) {
                                                        return;
                                                }

                                                var meshMin = info.boundingBox.minimumWorld;
                                                var meshMax = info.boundingBox.maximumWorld;

                                                if (!min || !max) {
                                                        min = meshMin.clone();
                                                        max = meshMax.clone();
                                                        return;
                                                }

                                                min = BABYLON.Vector3.Minimize(min, meshMin);
                                                max = BABYLON.Vector3.Maximize(max, meshMax);
                                        });

                                        if (!min || !max) {
                                                return;
                                        }

                                        var center = min.add(max).scale(0.5);
                                        var extents = max.subtract(min);
                                        var radius = Math.max(extents.x, extents.y, extents.z) * 1.75;

                                        camera.setTarget(center);
                                        camera.radius = Math.max(radius, 2.5);
                                }

                                function ensureLocalViewer() {
                                        var host = document.querySelector('.bolin-scene-viewer-glb');

                                        if (!host || !window.BABYLON || localViewerState.initialized) {
                                                return;
                                        }

                                        var canvas = document.getElementById('bolin-local-scene-canvas');

                                        if (!canvas) {
                                                canvas = document.createElement('canvas');
                                                canvas.id = 'bolin-local-scene-canvas';
                                                canvas.style.position = 'absolute';
                                                canvas.style.inset = '0';
                                                canvas.style.width = '100%';
                                                canvas.style.height = '100%';
                                                canvas.style.display = 'block';
                                                canvas.style.zIndex = '0';
                                                host.insertBefore(canvas, host.firstChild);
                                        }

                                        var existingCanvas = host.querySelector('canvas:not(#bolin-local-scene-canvas)');
                                        if (existingCanvas) {
                                                existingCanvas.style.display = 'none';
                                        }

                                        host.style.position = 'relative';

                                        var engine = new BABYLON.Engine(canvas, true, {
                                                preserveDrawingBuffer: true,
                                                stencil: true,
                                                antialias: true
                                        });
                                        var scene = new BABYLON.Scene(engine);
                                        scene.clearColor = new BABYLON.Color4(0.96, 0.96, 0.96, 1);

                                        var camera = new BABYLON.ArcRotateCamera(
                                                'bolinCamera',
                                                Math.PI / 2.15,
                                                Math.PI / 2.35,
                                                6,
                                                BABYLON.Vector3.Zero(),
                                                scene
                                        );
                                        camera.lowerRadiusLimit = 2.2;
                                        camera.upperRadiusLimit = 20;
                                        camera.wheelPrecision = 45;
                                        camera.panningSensibility = 1200;
                                        camera.attachControl(canvas, true);

                                        var lightA = new BABYLON.HemisphericLight('bolinLightA', new BABYLON.Vector3(0, 1, 0), scene);
                                        lightA.intensity = 1.25;
                                        var lightB = new BABYLON.DirectionalLight('bolinLightB', new BABYLON.Vector3(-0.5, -1, -0.75), scene);
                                        lightB.position = new BABYLON.Vector3(3, 6, 3);
                                        lightB.intensity = 1.0;

                                        BABYLON.SceneLoader.ImportMeshAsync('', 'assets/models/', 'keyboard-8.glb', scene).then(function () {
                                                fitCameraToScene(camera, scene);
                                                engine.resize();
                                        }).catch(function (error) {
                                                console.error('Local 3D viewer failed to load:', error);
                                        });

                                        engine.runRenderLoop(function () {
                                                scene.render();
                                        });

                                        window.addEventListener('resize', function () {
                                                engine.resize();
                                        });

                                        localViewerState.initialized = true;
                                        localViewerState.engine = engine;
                                        localViewerState.scene = scene;
                                        localViewerState.canvas = canvas;
                                }

                                function revealScene() {
                                        var wrapper = getSceneWrapper();

                                        if (!wrapper) {
                                                return false;
                                        }

                                        wrapper.classList.remove('hide');
                                        wrapper.classList.add('loaded');
                                        wrapper.classList.add('show');
                                        wrapper.style.display = 'block';
                                        wrapper.style.visibility = 'visible';
                                        wrapper.style.opacity = '1';
                                        wrapper.style.pointerEvents = 'auto';

                                        ensureLocalViewer();

                                        window.dispatchEvent(new Event('resize'));
                                        requestAnimationFrame(function () {
                                                window.dispatchEvent(new Event('resize'));
                                        });

                                        wrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                        return false;
                                }

                                function hideScene() {
                                        var wrapper = getSceneWrapper();

                                        if (!wrapper) {
                                                return false;
                                        }

                                        wrapper.classList.add('hide');
                                        wrapper.classList.remove('show');
                                        wrapper.style.display = 'none';
                                        return false;
                                }

                                window.bolinOpenScene = revealScene;
                                window.bolinCloseScene = hideScene;
                        }());
                        </script>


